COLLS([{"key":"tafsirnoor","ar":"تفسير نور الهدى","ur":"تفسیر نور الہدیٰ","en":"Tafsir Noor al-Huda","sub":{"ur":"جلد 1 تا 4 — سورۃ الفاتحہ تا سورۃ الاعراف (پارہ 8)؛ جمع و ترتیب: ابو حمزہ عبد الخالق صدیقی، حافظ عبد الرؤف محمدی؛ نظر ثانی: شیخ الحدیث عبد الوحید ساجد حفظہ اللہ","ar":"المجلدات 1–4 — من الفاتحة إلى الأعراف؛ جمع وترتيب: أبو حمزة عبد الخالق الصديقي وحافظ عبد الرؤوف محمدي","en":"Volumes 1–4 — al-Fatiha to al-Araf; compiled by Abu Hamza Abdul Khaliq Siddiqi and Hafiz Abdul Rauf Muhammadi"},"sections":[[1,"سورۃ الفاتحہ",1,37,"سورة الفاتحة"],[2,"سورۃ البقرہ (پارہ 1)",38,204,"سورة البقرة"],[3,"سورۃ البقرہ (پارہ 2)",205,395,"سورة البقرة"],[4,"سورۃ البقرہ (پارہ 3)",396,467,"سورة البقرة"],[5,"سورۃ آل عمران (پارہ 3)",468,554,"سورة آل عمران"],[6,"سورۃ آل عمران (پارہ 4)",555,714,"سورة آل عمران"],[7,"سورۃ النساء (پارہ 4)",715,794,"سورة النساء"],[8,"سورۃ النساء (پارہ 5)",795,1033,"سورة النساء"],[9,"سورۃ النساء (پارہ 6)",1034,1081,"سورة النساء"],[10,"سورۃ المائدہ (پارہ 6)",1082,1259,"سورة المائدة"],[11,"سورۃ المائدہ (پارہ 7)",1260,1291,"سورة المائدة"],[12,"سورۃ الانعام (پارہ 7)",1292,1380,"سورة الأنعام"],[13,"سورۃ الانعام (پارہ 8)",1381,1468,"سورة الأنعام"],[14,"سورۃ الاعراف (پارہ 8)",1469,1564,"سورة الأعراف"],[15,"ضروری نوٹس",1565,1565]],"prose":true,"langs":["ur"],"files":{"ur":[[1,57,"tafsirnoor_ur_1_4a277c.js"],[58,84,"tafsirnoor_ur_2_03f23b.js"],[85,121,"tafsirnoor_ur_3_4519d5.js"],[122,150,"tafsirnoor_ur_4_b901c2.js"],[151,177,"tafsirnoor_ur_5_facab7.js"],[178,199,"tafsirnoor_ur_6_69414f.js"],[200,225,"tafsirnoor_ur_7_d05e76.js"],[226,267,"tafsirnoor_ur_8_26c00e.js"],[268,331,"tafsirnoor_ur_9_c7915d.js"],[332,389,"tafsirnoor_ur_10_871256.js"],[390,422,"tafsirnoor_ur_11_d67313.js"],[423,463,"tafsirnoor_ur_12_edc788.js"],[464,483,"tafsirnoor_ur_13_91dea2.js"],[484,521,"tafsirnoor_ur_14_62b0db.js"],[522,572,"tafsirnoor_ur_15_c2fe3c.js"],[573,613,"tafsirnoor_ur_16_f350a1.js"],[614,659,"tafsirnoor_ur_17_288c09.js"],[660,699,"tafsirnoor_ur_18_50bb3c.js"],[700,767,"tafsirnoor_ur_19_b65568.js"],[768,834,"tafsirnoor_ur_20_e8542f.js"],[835,880,"tafsirnoor_ur_21_4e2c36.js"],[881,939,"tafsirnoor_ur_22_e06fb4.js"],[940,981,"tafsirnoor_ur_23_ef819b.js"],[982,1023,"tafsirnoor_ur_24_9d643f.js"],[1024,1068,"tafsirnoor_ur_25_99609c.js"],[1069,1109,"tafsirnoor_ur_26_e55928.js"],[1110,1156,"tafsirnoor_ur_27_d1a160.js"],[1157,1196,"tafsirnoor_ur_28_d27322.js"],[1197,1244,"tafsirnoor_ur_29_b37000.js"],[1245,1279,"tafsirnoor_ur_30_e9d4d0.js"],[1280,1295,"tafsirnoor_ur_31_a98caa.js"],[1296,1324,"tafsirnoor_ur_32_232987.js"],[1325,1367,"tafsirnoor_ur_33_0949e8.js"],[1368,1400,"tafsirnoor_ur_34_1b083a.js"],[1401,1444,"tafsirnoor_ur_35_7d32e5.js"],[1445,1481,"tafsirnoor_ur_36_3424c6.js"],[1482,1512,"tafsirnoor_ur_37_42208d.js"],[1513,1562,"tafsirnoor_ur_38_2db0d3.js"],[1563,1565,"tafsirnoor_ur_39_17d21d.js"]]},"count":1565,"intro":[["عرض ناشر",["بالله الرحمن الرحيم","اَلْحَمْدُ لِلّهِ رَبِّ الْعَلَمِيْنَ وَالصَّلَاةُ وَالسَّلَامُ عَلى سَيِّدِ الْأَنْبِيَاءِ وَالْمُرْسَلِيْنَ، أَمَّا بَعد! اللہ عز وجل نے لوگوں کی رشد و ہدایت کے لیے انبیاء ورسل علی الہ دین حق کے مبلغ اور داعی بنا کر بھیجے۔ ان کے مخالفین راہ حق سے برگشتہ کرنے کے لیے ہر طرح کے ہتھکنڈے استعمال کرتے رہے۔ گمراہی و ضلالت سے بچنے اور راہ ہدایت پر مستقیم رہنے کا ہر دور میں ایک ہی اصول اور ضابطہ رہا کہ اللہ تعالیٰ کے فرامین کی تعمیل اور اُس وقت کے پیغمبر کا اتباع کیا جائے۔ اللہ کے ہر پیغمبر علیہم کی اس دعوت کو قرآن نے بیان کیا ہے: فَاتَّقُوا اللهَ وَأَطِيعُونِ (آل عمران : 50) اللہ کا تقویٰ اختیار کرو اور میری اطاعت کرو ۔ “ خاتم النبیین جناب محمد رسول اللہ علی ال ی م تشریف لائے تو آپ نے بھی وحی کے اتباع کو راہ حق پر قائم رہنے اور گمراہی سے تحفظ کا ضامن قرار دیا۔","(تَرَكْتُ فِيْكُمْ أَمْرَيْنِ لَنْ تَضِلُّوْا مَا تَمَسَّكْتُمْ بِهِمَا: كِتَابُ اللهِ وسُنَّةُ رَسُوْلِهِ ))","(مؤطا مالك : 321/2)","میں تم میں دو چیزیں چھوڑے جارہا ہوں جب تک ان کو مضبوطی سے تھامے رکھو گے گمراہ نہیں ہو گے: ایک اللہ کی کتاب، اور دوسرے اس کے رسول کی سنت ۔“ اہل اسلام کو اس پر عمل کی دعوت دی گئی ہے۔ صحابہ کرام بھی انہم نے اپنے آپ کو قولاً وفعلاً قرآن وحدیث کے سانچے میں","ڈھال دیا تھا۔ اللہ تعالیٰ نے ان کو عزت و شرف سے نوازا اور ان کے ایمان کو نمونہ قرار دیا۔","فَإِنْ آمَنُوا بِمِثْلِ مَا أَمَنْتُم بِهِ فَقَدِ اهْتَدَوا) (البقرة : 137)","پس اگر وہ اس چیز پر ایمان لائیں جس پر تم ایمان لائے ہو تو یقیناً وہ ہدایت پاگئے ۔“","قرآن مجید اللہ تعالیٰ کی وہ عظیم اور آخری کتاب ہے جو انسانیت کے لیے سراسر ہدایت ، نور اور رحمت ہے۔ یہ کتاب نہ صرف عقائد کی اصلاح کرتی ہے بلکہ اخلاق، اعمال، معاملات اور زندگی کے ہر پہلو میں انسان کی رہنمائی کرتی ہے چونکہ قرآن مجید کے معانی نہایت وسیع ، گہرے اور ہمہ گیر ہیں اس لیے اُمت مسلمہ میں آغاز ہی سے اس کی تفسیر و تشریح کا سلسلہ جاری رہا ہے اور ہر دور میں اہل علم نے اپنے اپنے اسلوب اور فہم کے مطابق اس عظیم ذمہ داری کو ادا کیا ہے۔ تفسیر نور الہدیٰ اس علمی روایت کی ایک ادنی کوشش ہے جس کا مقصد یہ ہے کہ قرآن مجید کے معانی و مفاہیم کو قاری کے سامنے آسان، جامع اور قابل فہم انداز میں پیش کیا جائے ، ساتھ ہی علمی امانت اور دیانت کا پورا لحاظ رکھا جائے۔ اس تفسیر میں متعدد معتبر اور معروف تفاسیر سے استفادہ کیا گیا ہے ان تفاسیر کو یکجا کرنے کا مقصد محض اقوال کا انبار لگانا نہیں، بلکہ ایک ہی مقام پر مختلف علمی زاویوں کو سامنے لا کر جامع فہم پیدا کرنا ہے۔","تفسیر نورالہدی کی امتیازی خصوصیت یہ ہے کہ اس میں :","آثار و احادیث پر مبنی تشریح","ساده و عام فہم وضاحت","لغوی، سباقی اور بیانی پہلو","اور خلاصہ و نتیجہ خیز مفہوم","سب کو ایک متوازی ترتیب کے ساتھ پیش کیا گیا ہے تاکہ عام قاری بھی فائدہ اٹھا سکے اور طالب علم کوعلمی گہرائی حاصل ہو۔ یہ تفسیر اس حقیقت کو بھی واضح کرتی ہے کہ مفسرین کے مابین اختلاف اکثر اختلاف تضاد نہیں بلکہ اختلاف تنوع ہوتا ہے۔ مختلف تفسیری اقوال دراصل ایک ہی آیت کے مختلف پہلوؤں کو اجا گر کرتے ہیں جس سے قاری کا ذہن وسیع ہوتا ہے اور وہ قرآن حکیم کو محدود فہم کے بجائے ہمہ گیر نظر سے دیکھنے لگتا ہے۔ تعلیمی اعتبار سے تفسیر نور الہدی اساتذہ ، طلبہ، خطباء اور اہل علم کے لیے نہایت مفید ہے کیونکہ یہاں ایک ہی مقام پر مختصر مگر جامع مواد دستیاب ہوتا ہے دعوتی نقطہ نظر سے بھی یہ تفسیر اس لیے موثر ہے کہ اس میں زبان آسان ہے، اسلوب واضح ہے اور پیغام براہ راست دل تک پہنچنے والا ہے۔","اس تفسیر کی ترتیب میں اس امر کا خاص خیال رکھا گیا ہے کہ : غیر مستند اور ضعیف روایات سے حتی الامکان اجتناب کیا جائے۔ اختلافی مسائل میں اعتدال اور وضاحت اختیار کی جائے۔","اور قرآن مجید کے اصل پیغام اور مقصد کو مقدم رکھا جائے ۔ ہمیں امید ہے کہ تفسیر نور الہدی قاری کے لیے قرآن حکیم کے فہم میں آسانی، دل میں رغبت اور عمل میں رہنمائی کا ذریعہ بنے گی اور یہ تفسیر ایک ہی وقت میں آسان فہم قاری اور گہری نظر رکھنے والے طالب علم دونوں کے لیے مفید ہوگی ۔ دین و دنیا کے تمام امور کو کتاب وسنت کے تناظر میں دیکھنا ضروری ہے۔ ہماری زندگی کے تمام معاملات کا حل اللہ کی کتاب اور اس کے رسول صلی اللہ علیہ وسلم کی سیرت طیبہ میں موجود ہے۔ امت مسلمہ کے افتراق و انتشار کا سبب کتاب وسنت سے دوری ہے۔ حالانکہ فی زمانہ ہر زبان میں قرآن کے تراجم و تفاسیر اور کتب احادیث کے مختلف زبانوں میں ترجموں نے ایک عام انسان کے لیے کتاب وسنت تک رسائی کو آسان ترین بنا دیا ہے۔ محدثین اور سیرت نگاروں نے اپنی تالیفات کے ذریعہ ہر دور کے تقاضوں کے مطابق عوام الناس کی راہنمائی کا فریضہ انجام دیا۔ چنانچہ انہی آئمہ کے نقش قدم پر چلتے ہوئے ہم نے مختلف تفاسیر : ابن کثیر، السعدی، تیسیر الرحمن، تیسیر القرآن، احسن البیان اور اصدق البیان کو اختصار کے ساتھ یکجا کرنے کی ادنی سی سعی کی ہے اللہ تعالیٰ سے دعا ہے کہ وہ اس کاوش کو قبول فرمائے ، اسے علم نافع کا ذریعہ بنائے اور ہمیں قرآن حکیم کو سمجھنے، اس پر عمل کرنے اسے دوسروں تک پہنچانے کی توفیق عطا فرمائے۔آمین یا رب العالمین جب میں قرآن کریم کی تفاسیر کا مطالعہ کرتا تھا تو اکثر دل کو مکمل اطمینان حاصل نہیں ہوتا تھا کئی تفاسیر کو دیکھنے کے بعد بھی بعض آیات کی مراد اور اللہ عزوجل کے کلام کا اصل مقصود پوری طرح واضح نہ ہو پاتا۔ اسی احساس نے یہ خیال پیدا کیا کہ ایک ایسی تفسیر ہونی چاہیے جو کم از کم اس درجے کی وضاحت فراہم کرے کہ قاری آیت کا مفہوم اور اللہ تعالیٰ کا منشا بخوبی سمجھ سکے اس سوچ نے اس تفسیر کی بنیاد رکھی۔ ابتدا میں پانچ، پھر چھ تفاسیر کو یکجا کرنے کا ارادہ کیا تا کہ مختلف اہل علم کی آراء سامنے رہیں اور مفہوم زیادہ واضح ہو سکے۔ اس مقصد کے لیے میں نے پہلے خود پھر حافظ عبد الرؤف محمدی اللہ کو اپنے ساتھ شامل کرنے کا فیصلہ کیا۔ ہم نے تین تین تفاسیر کا باقاعدہ مطالعہ کر کے ان کا خلاصہ اور لب لباب یکجا کیا۔","اس دوران مختلف اہل علم سے مشورہ بھی حاصل کیا گیا۔ تمام علماء کرام نے نہ صرف حوصلہ افزائی فرمائی بلکہ دعاؤں سے بھی نوازا۔ ان میں بالخصوص شیخ عبد العزيز العلوی ہے شیخ الحدیث جامعہ سلفیہ فیصل آباد، شیخ القرآن عبد اللہ امجد چھتوی اڑانے شیخ الحدیث ستیانہ بنگلہ اور مفتی عبد الحنان زاہد اللہ جامعہ سلفیہ فیصل آباد قابل ذکر ہیں۔ جب شیخ عبد اللہ چھتوی ہم اللہ کے سامنے یہ بات رکھی کہ ہم چھ تفاسیر کو جمع کرنے کا ارادہ رکھتے ہیں اور اس علمی کام میں تکرار، ضعیف، غیر ثابت اور مثل نظر روایات کو مکمل طور پر الگ کر دیا جائے گا نیز صرف انہی تفاسیر کو شامل کیا جائے گا جو اہل علم کے نزدیک معروف و مقبول ہیں اور جن کے مصنفین کا منہج قرآن وسنت اور فہم سلف صالحین ، بالخصوص صحابہ کرام خالیم کے مطابق ہے تو یہ سن کر شیخ رحمہ اللہ نہایت مسرور ہوئے۔ انہوں نے اس منصوبے کو علم دین کی دنیا میں ایک عظیم اور بابرکت قدم قرار دیا اور فرمایا کہ یہ محض ایک تحقیقی کاوش نہیں بلکہ اسلام اور قرآن حکیم کی ایک مخلصانہ خدمت ہے۔ شیخ بڑالے کے چہرے پر خوشی نمایاں تھی اور ان کے کلمات سے حوصلہ افزائی جھلک رہی تھی انہوں نے خلوص دل کے ساتھ بار بار دعائیں دیں کہ اللہ تعالیٰ آپ لوگوں کو اس کام میں اخلاص عطا فرمائے آپ کا مددگار اور محافظ ہو اور اس کوشش کو قبولیت عامہ نصیب فرمائے۔ شیخ اللہ نے یہ بھی فرمایا کہ اگر یہ کام اس منہج اور احتیاط کے ساتھ مکمل ہو گیا تو یہ اہل علم اور عام قارئین دونوں کے لیے ایک معتبر اور قابل اعتماد علمی سرمایہ ثابت ہوگا جس سے قرآن فہمی میں درست رہنمائی میسر آئے گی اور بہت سی الجھنیں دور ہوں گی۔","میرے ساتھ حافظ عبدالرؤف محمدی اللہ نے نہایت اخلاص، محنت اور دیانت کے ساتھ اس کام میں حصہ لیا۔ اللہ تعالیٰ انہیں","اس کا بہترین اجر عطا فرمائے اور اس کوشش کو قبول فرمائے۔","ہم نے اپنے ادارہ انصار السنہ پبلی کیشنز سے بزبان اردو شائع کر کے قرآن مجید کے ساتھ اپنی محبت کا ثبوت دیا ہے۔ اللہ تعالیٰ جزائے خیر عطا فرمائے شیخ الحدیث عبد الوحید ساجد اللہ کو جنہوں نے تفسیر نور الہدی کی پروف ریڈنگ اور نظر ثانی کا کام کیا۔ ہم ان کے تہہ دل سے شکر گزار ہیں۔ اسی طرح ہم فضیلۃ الشیخ عبد الغفار بن عبد الخالق اللہ کے بھی ممنون وشکر گزار ہیں جنہوں نے اس علمی کام میں بھر پور معاونت فرمائی اور پروف ریڈنگ کے مراحل میں اپنا قیمتی تعاون پیش کیا۔ اللہ تعالیٰ دونوں علماء کرام کی مساعی جمیلہ کو شرف قبولیت عطا فرمائے۔ آمین آخر میں ہم اپنے محسن فضیلۃ الشیخ عبد اللہ ناصر رحمانی اللہ کے انتہائی شکر گزار ہیں جو اپنی مصروفیات کے باوجود ادارہ کی سر پرستی کر رہے ہیں ، ان کی ترغیب ، تشیع اور اشراف کا ہی نتیجہ ہے کہ مختلف علوم اسلامیہ کی کتب زیور طباعت سے آراستہ ہوکر منصہ شہود پر آ رہی ہیں۔ کثر الله أمثاله في العالم۔","میں اپنے سینئر ایڈوائزر ڈاکٹر حافظ حامد محمود الخضری کے لیے بھی دعا گو ہوں کہ اللہ تعالیٰ انہیں صحت اور ایمان کی زندگی","بخشے کیونکہ وہ روز اول سے ادارہ میں اخلاص کے ساتھ ہمارے ساتھ برابر کے شریک ہیں۔","جناب ابو مؤمن منصور احمد اللہ اور اُن کے فرزند ارجمند جناب مؤمن الله (اسلامی اکادمی ) کی تمام کوششیں اللہ عز وجل","اپنی بارگاہ میں قبول فرمائے ، کیونکہ ان کے تعاون سے ان کتابوں کی اشاعت ہو رہی ہے۔ اللہ تعالیٰ کا شکر ادا کرتا ہوں کہ اس نے میرے ساتھ دو ایسے مخلص اور محنتی حضرات کو شامل فرمایا جس کے تعاون کے بغیر یہ کام ممکن نہ تھا خاص طور پر میں بھائی جان ناظر صاحب کا دل کی گہرائیوں سے شکر ادا کرتا ہوں جن کی توجہ، رہنمائی اور حوصلہ افزائی سے اس کام کا آغاز ہوا انہوں نے نہ صرف اس منصوبے کی اہمیت کو سمجھا بلکہ اس کے عملی پہلوؤں کو سنبھالا اور ہر مرحلے میں بھر پور تعاون فراہم کیا۔","اسی طرح میں حافظ اسعد محمود سلفی اللہ کا بھی تہہ دل سے شکر گزار ہوں جنہوں نے بھائی ناظر صاحب کے ساتھ مل کر اس پورے کام کو منظم انداز میں آگے بڑھایا۔ اس تفسیر کے مختلف مراحل میں دونوں حضرات نے غیر معمولی محنت اور اخلاص اور ذمہ داری کا ثبوت دیا اور ہر موقع پر آگے بڑھ کر اس کام کو پایہ تکمیل تک پہنچانے میں کردار ادا کیا۔ حقیقت یہ ہے کہ ہماری فہم قرآن کلاس نیویارک کی مسلسل کاوش ، تعاون اور قربانی کے بغیر بھی یہ علمی خدمت ممکن نہ تھی۔ ابو طلحہ محمد اشفاق، اسجد محمود منج ، عبد الوحید ، فیصل خان، محمد عرفان انتصار، ابرار احمد، محمد اکبر، محمد شاہد، محمد افضال، فیصل احمد، رشید خاں، زبیر، حکیم محمد الیاس، اللہ تعالیٰ ان سب کی اس محنت کو اپنی بارگاہ میں قبول فرمائے ۔ ان کے علم وعمل میں برکت عطا کرے اور انہیں دنیا و آخرت میں بہترین جزا عطا فرمائے ۔ آمین میں اس موقع پر اپنے محترم ابو حفص محمد حسن اللہ کا دل کی گہرائیوں سے شکریہ ادا کرنا ضروری سمجھتا ہوں جنہوں نے میری کتب کی تیاری میں نہایت خلوص، محنت اور ذمہ داری کا مظاہرہ کیا۔ جب بھی میرے لکھے ہوئے متن میں کوئی بات واضح نہ ہو وہ بار بار مجھ سے رجوع کرتے اور جہاں ضرورت ہو وہاں متعلقہ کتابوں اور حوالہ جاتی مواد کی تحقیق بھی کر لیتے ہیں اور میں بھی انہیں صبح دوپہر شام تنگ کرتا رہتا ہوں۔ ان کی یہ خوبی ہے کہ وہ صرف کمپوزنگ تک محدود نہیں ہیں بلکہ علمی دیانت کے ساتھ ترتیب اور وضاحت میں علمی بھر پور تعاون کرتے ہیں۔ میرے مکمل پروجیکٹ میں برابر کے شریک ہیں۔ ان کی مسلسل محنت ، تعاون اور سنجیدگی ہماری کتب کے حسن میں اضافے کا ذریعہ بن رہی ہیں ۔ اللہ تعالیٰ انہیں جزائے خیر عطا فرمائے ان کے علم اور عمل میں برکت دے اور ان کی محنت کو قبول فرمائے ۔ آمین","میں اپنے محترم دوست محمد شاہد انصاری صاحب کا ساتھ اور اپنے پیارے دوست ابوذ بیح اللہ حیات کا بھی تہہ دل سے شکر گزار ہوں جو وقتاً فوقتاً نہایت مفید اور بصیرت افروز مشوروں سے میری رہنمائی فرماتے رہتے ہیں اللہ تعالیٰ انہیں جزائے خیر عطا فرمائے ۔ آمین","یہاں میں ایک ایسی بات عرض کرنا چاہتا ہوں جس کا حق ادا کرنا میرے لیے الفاظ میں ممکن نہیں بعض احساسات، بعض قربانیاں اور بعض تعاون ایسے ہوتے ہیں جو نہ زبان سے پوری طرح ادا کیے جاسکتے ہیں اور نہ ہی قلم ان کی گہرائی کو مکمل سمیٹ سکتا ہے۔ پھر بھی دل کے بوجھ کو ہلکا کرنے اور حق شکر کی ادنیٰ سی کوشش کے طور پر ان کا ذکر کرنا ضروری سمجھتا ہوں ۔ ان ہی عظیم احساسات میں میرے ایک نہایت مخلص اور دردِ دل رکھنے والے بھائی جان محمد طارق جاوید ہ کا خصوصی ذکر ہے جنہوں نے برسوں تک میری بیرونی مصروفیات، دنیوی اور انتظامی ذمہ داریوں کو اپنے ذمہ لے کر مجھے فکری سکون عطا کیا انہوں نے مجھے غیر ضروری الجھنوں اور پریشانیوں سے آزاد رکھا تا کہ میں پوری یکسوئی کے ساتھ علم دین اور اس کی خدمت میں مشغول رہ سکوں ۔ ان کا خاموش تعاون بے لوث ساتھ اور مسلسل حوصلہ افزائی میرے لیے ایک عظیم نعمت ثابت ہوئی۔ اسی طرح میں اپنی اہلیہ کا بھی دل کی گہرائیوں سے شکر گزار ہوں جنہوں نے گھریلو زندگی کے تمام تقاضوں کو صبر ، حکمت اور حسن تدبیر کے ساتھ نبھایا۔ انہوں نے کبھی مجھے علمی و دینی مصروفیات سے روکا نہیں بلکہ ہر مرحلے پرسہولت ، تعاون اور اطمینان فراہم کیا۔ گزشتہ پینتیس برسوں سے ان کی مستقل قربانیاں، برداشت اور ایثار میرے لیے دین کے کام میں ثابت قدمی","کا ذریعہ بنتی رہیں۔ ان دونوں کے خلوص ، تعاون اور دعاؤں کے سائے میں اور اللہ تعالیٰ کے فضل و کرم اس کی رحمت اور عطا کردہ تو فیق سے لاحول ولا قوة الا بالله، وما توفیقی الا باللہ مجھے متعدد علمی کتب اور مختلف دینی و اصلاحی منصوبے مکمل کرنے کی سعادت نصیب ہوئی۔ اللہ عز وجل ہی کا شکر ہے کہ ان کوششوں کو قبولیت عطا فرمائی اور ان کے ذریعے آج دنیا کے مختلف حصوں میں لوگ فائدہ اُٹھا رہے ہیں۔ میں بارگاہ الہی میں نہایت عاجزی کے ساتھ دعا گو ہوں کہ اللہ تعالیٰ میرے اس بھائی اور میری اہلیہ کی ان تمام کاوشوں کو اپنی بارگاہ میں قبول فرمائے ، ان کے درجات بلند کرے، ان کے اعمال کو میزان حسنات میں بھاری کر دے، ان کی لغزشوں کو","معاف فرمائے اور آخرت میں اپنی اپنی خاص رحمت، رضا اور دائگی کامیابی سے نوازے۔ آمین یا رب العالمین اللہ کے حضور سربسجود ہوکر دعا گو ہیں کہ وہ اس کتاب کو ہم گنہ گاروں کی نجات کا ذریعہ بنائے کہ اس کی رحمت بے شمار ہے۔ اللہ عز وجل اس عظیم کام کو ہمارے، ہمارے والدین، دوست احباب، معاونین ومساھمین اور ہمارے اساتذہ کرام کے لیے","صدقہ جاریہ بنائے۔","وَصَلَّى اللهُ تَعَالَى عَلى خَيْرِ خَلْقِهِ مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمْ","وكتبه","ابوحمزہ عبد الخالق صدیقی","رئیس : اداره انصار السنه پبلیکیشنز لاهور","Email: Akmian311@gmail.com"]],["تقریظ",["الحمد لله","بالله الرحمن الرحيم","رب العالمين والصلاة والسلام على سيد المرسلين، محمد وآله","وصحبه أجمعين، أما بعد:","قرآن مجید کلام اللہ ہے۔","وَلَقَد أَنْزَلْنَا إِلَيْكَ أَيْت بَيِّنت )) (البقرة: 99)","اور یقیناً ہم نے آپ کی طرف کھلی آیتیں نازل کی ہیں۔“","اور رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا:","((وَفَضْلُ كَلَامِ اللهِ عَلَى سَائِرِ الْكَلَامِ كَفَضْلِ اللَّهِ عَلَى خَلْقِهِ.","(حسن: جامع ترمذی، رقم : 2926)","کلام اللہ کی فضیلت دوسرے سارے کلاموں پر ایسی ہے جیسی خود اللہ کی برتری اپنی مخلوق پر “ یعنی جس طرح اللہ کی ذات اور نظیر ممکن نہیں ہے۔ اسی طرح اس کے کلام کی مثال اور نظیر بھی ممکن نہیں ہے، جس طرح اللہ سبحانہ وتعالیٰ ہر عیب اور نقص سے پاک ہے اسی طرح اس کا کلام بھی ہر عیب و نقص سے پاک ہے اور انسانی زندگی کے لیے کامل احکام و ہدایات پر مشتمل ہے، جس طرح اللہ رب العالمین پوری کائنات کا مالک اور حاکم ہے اسی طرح اس کا کلام بھی پوری انسانیت کے لیے عالمی قانون اور کتاب ہدایت ہے جو طریق اقوم“ یعنی سیدھا اور معتدل راستی بتاتی ہے۔ إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ (الاسراء: 9)","”یقینا یہ قرآن زندگی کا وہ طریقہ بتا تا ہے جو سب سے زیادہ صحیح اور متوازن و معتدل ہے۔“","اقوم کے معنی ہیں اَصْوَب یعنی سب سے زیادہ صحیح اور سیدھا راستہ لیکن قوام میں اعتدال اور توازن کے معنی بھی شامل ہیں یعنی ایسا راستہ اور طرز زندگی جو صحیح اور درست بھی ہو اور اس میں افراط و تفریط یعنی انتہا پسندی بھی نہ ہو بلکہ وہ توازن و اعتدال پر مبنی سیدھا راستہ ہو۔ علامہ قرطبی اللہ نے لکھا ہے کہ طریق اقوم اس راستے کو کہتے ہیں جو قریب بھی ہو، آسان بھی ہو اور خطرات سے محفوظ بھی تفسير تو الفي ہوایسا راستہ وہی ہے جو قرآن نے بتایا ہے اور جو اللہ کا پسندیدہ راستہ ہے یعنی اسلام۔ نزول قرآن سے پہلے انسانیت جہالت کے اندھیروں کی لپیٹ میں تھی کہ نور قرآن کے نزول کا آغاز ہوا اور انسانیت","اندھیروں کی لپیٹ سے نکل کر علم کے انوار سے منور ہوئی اور اس روشنی میں اسے طریق اقوم نظر آنے لگا۔ كتب انْزَلْنَهُ إِلَيْكَ لِتُخْرِجَ النَّاسَ مِنَ الظُّلمتِ إِلَى النُّورِ بِإِذْنِ رَبِّهِمْ إِلَى صِرَاطِ الْعَزِيزِ الْحَمِيدِ ) (ابراهيم (1)","یہ ایک کتاب ہے جسے ہم نے آپ کے پاس اتارا ہے تا کہ تم لوگوں کو ان کے رب کے حکم سے اندھیروں سے نکال کر روشنی میں لے آؤ یعنی غالب اور لائق حمد اللہ کے راستے کی جانب لے آؤ۔“ ظلمات سے جاہلانہ کافرانہ اور مشرکانہ عقائد و اعمال مراد ہیں جن کے متعدد انواع واقسام ہیں، نور سے توحید کا عقیدہ مراد ہے جس کی متعدد فروع ہیں اور صِرَاطِ الْعَزِيزِ الْحَبِیدِ کا بتایا ہوا طریق اقوم اور صراط مستقیم مراد ہے۔ نزول قرآن سے قبل اولاد آدم قسم قسم کی اعتقادی، اخلاقی اور معاشرتی بے اعتدالیوں اور بیماریوں میں مبتلا ہو چکی تھی اور کسی کے پاس ان بیماریوں سے نجات کے لیے نسخہ شفا موجود نہیں تھا کہ اللہ نے نسخہ شفا اتارا اور جس نے بھی یہ نسخہ استعمال کیا وہ ان بیماریوں کی لپیٹ سے نکل کر شفایاب ہوا اور دوسروں کے لیے روحانی واخلاقی طبیب ثابت ہوا۔","يَاأَيُّهَا النَّاسُ قَدْ جَاءَ تَكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَاء لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ ) (یونس : 57)","”اے لوگو! یقیناً آگئی ہے تمہارے پاس تمہارے رب کی جانب سے نصیحت اور علاج ان بیماریوں کا جوسینوں اور دلوں میں ہیں اور ہدایت و رحمت ایمان لانے والوں کے لیے۔“ موعظہ اور وعظ اس کلام کو کہا جاتا ہے جو دلوں کو نرم کرنے والا ہو ، متاثر کرنے والا ہو، وعد و وعید ، ترغیب و ترہیب اور تذکیر کے ذریعے ایمان و عمل پر آمادہ کرنے والا ہو، قرآن پر یہ ساری صفات صادق آتی ہیں اس لیے اسے موعظہ کہا گیا ہے۔ شِفَاء کے معنی ہیں مَا يُبْرِءُ مِنَ السَّقَم وہ چیز جو مرض کو ہٹا دیتی ہو، مَا فِي الصُّدُورُ سے مراد دل کی بیماریاں ہیں یعنی تکبر و سرکشی ، حسد و عناد، حرص دنیا، فکر آخرت سے غفلت اور انہی امراض کی وجہ سے نظریات باطلہ اور عقائد فاسدہ ان تمام امراض قلبیہ کی دوا اور نسخہ شفاء قرآن مجید ہے اور جو لوگ اس نسخہ شفا کو مانتے ہیں اور اسے استعمال کرتے ہیں تو ان کے لیے یہ دنیا میں ہدایت ہے اور آخرت میں رحمت ہے اور چاہیے کہ ایمان والے اس ہدایت اور رحمت پر خوش ہو جا ئیں ۔ قُلْ بِفَضْلِ اللهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْيَفْرَحُوا هُوَ خَيْرٌ مِمَّا يَجْمَعُونَ ) ( يونس : 58)","\" کہہ دیجیے کہ اللہ کے فضل اور رحمت پر خوش ہو جا ئیں یہ بہتر ہے دنیا کی ان چیزوں سے جن کو یہ لوگ جمع کرتے ہیں۔“ سیدنا عبد اللہ بن عباس یا ہا سے مروی ہے کہ فضل سے اسلام مراد ہے اور رحمت سے قرآن مراد ہے اور سیدنا ابوسعید خدری یا اللہ کا قول اس کے برعکس ہے کہ فضل سے قرآن مراد ہے اور رحمت سے اسلام مراد ہے۔لیکن قاضی ابن عطیہ غرطانی باللہ نے اپنی تفسیر المحررالوجیز میں لکھا ہے کہ الفاظ اور سیاق کلام سے معلوم ہوتا ہے کہ فضل سے دین کی طرف ہدایت اور اتباع شریعت مراد ہے اور رحمت سے جنت مراد ہے جو اتباع شریعت کی جزا ہے یعنی اللہ نے قرآن کے نسخہ کیمیا کے ذریعے تم کو امراض قلبیہ سے شفا دی ہے، سیدھی راہ پر چلنے کی توفیق دی ہے اور اس کے بدلے میں تم کو رحمت اخروی سے نوازے گا اور یہ ہدایت و رحمت دنیا کی ان تمام چیزوں سے بہتر ہے جسے یہ ابناء الدنیا سمیٹتے رہتے ہیں اس لیے تم اس ہدایت اور رحمت پر خوش ہو جاؤ۔ سورہ یونس کی مذکورہ دو آیات سے معلوم ہوا کہ قرآن خواب غفلت سے بیدار کرنے کے لیے وعظ و تذکیر بھی ہے، روحانی، قلبی اور اخلاقی بیماریوں سے شفا بھی ہے۔ ایمان والوں کے لیے ہدایت اور رحمت بھی ہے اور قرآن کا علم نافع تمام اشیاء دنیا اور تمام علوم دنیا سے زیادہ بہتر اور نفع بخش ہے۔ مِمَّا يَجْمَعُونَ میں اشیاء د نیو یہ اور علوم دنیو یہ دونوں شامل ہیں۔ ان دونوں میں افادیت ہے لیکن علوم دینیہ اور علوم قرآنیہ کی افادیت اور فضیلت ان سے بدرجہا زیادہ ہے۔ ھو","خَيْرٌ مِّمَّا يَجْمَعُونَ میں جو حقیقت بیان کی گئی ہے۔","رسول اللہ صلی اللہ علیہ وسلم نے اس کا ذکر اس طرح کیا ہے کہ:","((خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَه)) (صحیح بخاری، رقم : 5027)","تم میں سے بہترین اور سب سے زیادہ نفع پہنچانے والا شخص وہ ہے جس نے قرآن کا علم حاصل کیا اور دوسروں کو","سکھایا ہو۔“","قرآن پڑھنے پڑھانے والوں اور سمجھنے سمجھانے والوں کے بارے میں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے کہ: أهْلُ الْقُرْآنِ هُمْ اَهْلُ اللهِ وَخَاصَّتُه .","(صحیح سنن ابن ماجه رقم: 215 مستدرك حاكم : 743/1)","قرآن والے ہی اللہ والے ہیں اور اس کے خاص بندے ہیں ۔“","66","صحیح مسلم کی حدیث میں آیا ہے کہ مساجد اور مدارس میں قرآن پڑھنے پڑھانے والوں کو سکون قلبی اور طمانینت قلبی نصیب ہوتی ہے، اللہ کی رحمت ان کو ڈھانپ لیتی ہے، اللہ کے معصوم فرشتے محبت کی وجہ سے ان کو گھیر لیتے ہیں اور خود اللہ ان کا ذکر خیر ملائکہ مقربین کی مجلس میں کرتے ہیں۔ (صحیح مسلم، رقم : 2700 سنن ترمذی، رقم : 3377)","معلوم ہوا کہ علوم القرآن تمام علوم سے بہترین ہیں اور علماء قرآن دوسرے تمام علماء سے افضل ہیں۔","علم تفسیر و مفسرین","لفظ تفسیر کا سہ حرفی مادہ فسر ہے، جس کے معنی ہیں ظاہر کرنا، کھول کر بیان کرنا اور بے حجاب کرنا۔ کسی لفظ کی تشریح و توضیح کو تفسیر کا نام اس لیے دیا گیا ہے کہ گویا اس کے مطلوب و مقصود کو بے حجاب کر دیا جاتا ہے۔ یہ تفسیر کا لغوی مفہوم ہے جہاں تک تفسیر کے اصطلاحی معنی کا تعلق ہے امام زرکشی نے تفسیر کی تعریف میں ان الفاظ میں کی ہے:","تفسیر ایک ایسا علم ہے جس کی مدد سے قرآن کریم کے مطالب و معانی معلوم کیے جاتے اور اس میں مندرجہ احکام و مسائل اور اسرار وحکم سے بحث کی جاتی ہے۔“ (البربان)","(1) تفسیر عہد نبوی میں :","تفسیر کا ارتقاء","قرآن عزیز عربی میں نازل ہوا تھا۔ اس وقت جو لوگ موجود تھے، عربی ان کی مادری زبان تھی۔ اس لیے قرآن کریم کے معانی و مطلب معلوم کرنے میں انہیں کوئی دقت پیش نہیں آتی تھی۔ تاہم بعض مقامات میں جہاں زیادہ اجمال ہوتا ہے صحابه خود رسول اللہ صلی اللہ علیہ وسلم سے دریافت کر لیا کرتے تھے ۔ نبی اکرم صلی اللہ علیہ وسلم کو اللہ عزوجل نے جہاں دیگر مناصب جلیلہ پر فائز کیا تھا وہاں ایک منصب عالی قرآن عزیز کے مفسر و تر جمان ہونے کا بھی تھا۔","وَ أَنْزَلْنَا إِلَيْكَ الذِكرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمُ )) (النحل : 44)","اور ہم نے آپ پر قرآن نازل کیا تا کہ آپ اسے لوگوں کے لیے واضح کر دیں۔“","چنانچہ تفسیر کا سب سے پہلا بیش قیمت سرمایہ تفسیری روایات ہیں جو مختلف کتب حدیث میں منقول ہیں۔ امام بخاری جملہ نے انہی احادیث کو یکجا کر کے کتاب تفسیر القرآن“ کے نام سے صحیح بخاری میں ایک مستقل عنوان قائم کیا اور ایسے ہی امام ترمذی رحمہ اللہ نے اپنی جامع میں تفسیری روایات کو یکجا کر کے ابواب تفسیر القرآن“ کے نام سے ایک مستقل عنوان قائم کیا۔ (2) تفسیر عصر صحابہ کرام میں:","رسول کریم سلام کے بعد جب اسلامی فتوحات کا دائرہ آگے بڑھا اور تمدن میں وسعت آئی تو دینی احکام میں نئی نئی صورتیں پیش آنے لگیں۔ اس کے زیر اثر قرآن عزیز کی آیات احکام پر غور و فکر کرنے کی بنا پڑی۔ تمام صحابہ کرام بھی اہم فہم قرآن میں برابر نہ تھے اور تفسیر کا طرز و انداز بھی مختلف تھا۔ صحابہ قرآن کی وہی تفسیر کرتے ، جو بالواسطہ یا بلا واسطہ رسول کریم ملی صلی اللہ علیہ وسلم سے سنی تھی یا جس آیت کا سبب نزول انھوں نے خود ملاحظہ کیا ہوتا یا جو چیز بطریق اجتہادان پر منکشف ہوتی۔ صحابہ کرام میں دس حضرات کو اس فن میں امتیاز حاصل تھا۔ خلفائے راشدین میں سے سب سے زیادہ تفسیری روایات سیدنا علی المرتضی ولی اللہ سے مروی ہیں۔ مگر بحیثیت مجموعی تمام صحابہ میں سب سے زیادہ تفسیری روایات سیدنا عبد اللہ بن عباس ایلنا) کی طرف منسوب ہیں۔ ان کے حلقہ درس نے نہایت وسعت حاصل کی ہزاروں شاگرد پیدا ہوئے۔","(3) تفسیر عہد تابعین عظام میں : عصر صحابہ کے ختم ہوتے ہی تفسیر قرآن کے ایک نئے دور کا آغاز ہوا۔ اس مرحلہ کی ابتدا عصر تابعین سے ہوئی۔ جنھوں نے صحابہ کے چشمہ فیض سے اپنی علمی پیاس بجھائی تھی۔ صحابہ کی طرح تابعین میں بھی بڑے نامور مفسرین پیدا ہوئے۔ ان میں سے مجاہد، عطا بن ابی رباح، عکرمہ، سعید بن جبیر، حسن بصری، ابوالعالیہ، ضحاک اور قتادہ یہ بہت ممتاز ہیں۔ غالباً سب سے پہلے اس فن کی جس نے ابتدا کی وہ سعید بن جبیر تھے عبد الملک بن مروان نے ان سے تفسیر لکھنے کی درخواست کی۔ چنانچہ انھوں نے اس کی فرمائش کے مطابق تفسیر لکھ کر دربار خلافت میں بھیج دی۔ عطاء بن دینار کے نام سے جو تفسیر مشہور ہے وہ درحقیقت یہی تفسیر ہے۔ (میزان الاعتدال للذہبی) مکہ، مدینہ اور کوفہ اس دور میں تفسیر کے اہم مراکز تھے۔ مکہ میں سیدنا عبد اللہ بن عباس بی) کے اصحاب و تلامذہ کا فیض جاری تھا۔ ان میں جناب مجاہد متوفی 104ھ کا پایہ بلند تھا۔ شیخ الاسلام ابن تیمیہ کا قول ہے کہ مجاہد کی تفسیر پر ائمہ مثلاً امام ثوری، امام شافعی ، احمد بن حنبل اور امام بخاری اعتماد کرتے تھے۔ مدینہ میں کتب تفسیر کی تاسیس سیدنا ابی بن کعب اللہ کی مساعی کی مرہون منت ہے۔ اکثر تابعین نے آپ سے کسب فیض کیا اور بکثرت تفسیری اقوال ان سے سن کر آگے پہنچائے ۔ تابعین مدینہ میں زید بن اسلم، ابوالعالیہ اور محمد بن کعب القرظی کے اسمائے گرامی قابل ذکر ہیں۔","کوفہ کے مکتب تفسیر کی بناسیدنا عبد اللہ بن مسعود نبی صلی اللہ علیہ وسلم کے ہاتھوں پڑی۔ اس مدرسہ کے وابستگان دامن میں سے علقمہ بن قیس مسروق اسود بن یزید اور عامر شعبی نے بہت شہرت حاصل کی۔ بصرہ میں حسن بصری کی ذات تفسیر قرآن میں مرجع","خلائق تھی۔","(4) تفسیر عصر تدوین میں :","اس دور کا آغاز عصر تدوین سے ہوتا ہے۔ اسی دور میں صحیح معنوں میں تفسیر نگاری کی بنا پڑی۔ یہ دور اموی خلافت کے اواخر سے لے کر خلافت عباسیہ کے اوائل تک پھیلا ہوا ہے۔ عصر تدوین سے پہلے تفسیری روایات احادیث نبویہ کے ساتھ مخلوط تھیں ۔ حدیث نبوی مختلف ابواب میں منقسم تھی اور ان میں ایک باب تفسیری روایات پر مشتمل ہوا کرتا تھا۔ اس مرحلہ پر پہنچ کر تفسیر حدیث نبوی سے الگ ہوگئی اور اس نے ایک جدا گانہ فن کی صورت اختیار کر لی۔ اب قرآنی ترتیب کے مطابق ہر ہر آیت اور سورت کی تفسیر مرتب کی جانے لگی ۔ اس میں ابن ماجہ، ابن جریر طبری، ابن ابی حاتم ، امام حاکم اور دیگر اکا بر محدثین نے حصہ لیا۔ یہ تفاسیر سند نبی کریم صلی اللہ علیہ وسلم اور صحابہ و تابعین و اتباع تابعین سے منقول ہیں۔ ان میں تفسیر بالماثور کے سوا دوسری کوئی چیز مذکور نہیں۔ البتہ ابن جریر طبری نے تفسیری اقوال ذکر کر کے ان کی توجیہ کی اور بعض کو راجح اور بعض کو مرجوح قرار دیا۔ جلال الدین سیوطی علم اللہ نے تفسیر ابن جریر کے بارے میں لکھا ہے:","اگر تم مجھ سے دریافت کرو کہ کس تفسیر پر اعتماد کیا جائے تو میں کہوں گا ابن جریر پر جس کے بارے میں علماء کا قول ہے کہ اس جیسی کوئی تفسیر نہیں لکھی گئی ۔“ تا ہم اس فرق و اختلاف کے باوجود اس دور کی تفسیر تفسیر بالماثور کے دائرہ میں محدود رہی البتہ اسناد کی شرط باقی نہ رہی۔ مفسرین سلف کے تفسیری اقوال کو بلا سند ذکر کرنے کا نتیجہ یہ ہوا کہ بہت سے من گھڑت اقوال نے تفسیر میں بار پایا اور اقوال صحیحہ وسقیمہ کے مابین امتیاز کرنے میں دشواری کا سامنا ہونے لگا۔","(5) تفسیر عصر تدوین کے بعد : یہاں سے تفسیر کے پانچویں مرحلہ کا آغاز ہوتا ہے۔ یہ تفسیر کا طویل ترین تاریخی دور ہے جو عباسی خلافت سے شروع ہوکر عصر حاضر تک پھیلا ہوا ہے۔ قبل ازیں تفسیر کا انحصار منقول روایات پر تھا۔ اس دور میں عقل و نقل میں امتزاج و اختلاط کا آغاز ہوا، صرف و نحو اور عربیت سے متعلق علوم مدون ہوئے، فقہی مسالک منظر عام پر آئے اور کلامی مسائل نے سر نکالا۔ عباسی خلافت میں گروہی تعصب آخری حد تک پہنچ گیا۔ مختلف اسلامی فرقے اپنے مخصوص افکار و عقائد کی دعوت دینے لگے۔ منطق و فلسفہ سے متعلق کتب کا یونانی سے عربی میں ترجمہ کیا گیا۔ اس کا نتیجہ یہ ہوا کہ یہ سب علوم تفسیر کے ساتھ گھل مل گئے ۔ جو شخص کسی علم وفن میں کمال رکھتا تھا، اس کی تفسیر اسی علم تک محدودرہ گئی ۔","چنانچہ نوی علماء نے جو تفاسیر لکھیں ان کونحوی مسائل سے بھر دیا۔ مثلاً زجاج نے اپنی تفسیر میں، واحدی نے البسیط میں اور ابوحیان نے البحر المحیط میں نحوی مہارت و براعت ہی کا ثبوت دیا ہے۔ جو لوگ علوم عقلیہ میں بصیرت رکھتے تھے انھوں نے اپنی کتب تفسیر کو حکماء و فلاسفہ کے اقوال کا پلندہ بنا دیا۔ امام فخر الدین رازی متوفی 606ھ کی تفسیر اسی انداز کی ہے۔ رازی کی تفسیر ”مفاتیح الغیب المعروف تفسیر کبیر آپ کا شاہکار ہے۔ امام صاحب کا انداز تفسیر یہ ہے کہ عقلی و نقلی قسم کے جس قدر تفسیری اقوال مختلف تفاسیر میں پراگندہ ہیں۔ امام صاحب نے ان سب کو اپنی تفسیر میں جمع کر دیا ہے فلسفہ قدیم کی رو سے اکثر مقصد سے دور نکل جاتے ہیں۔","مبتدعین نے جو تفاسیر لکھیں ان کو اپنی پسندیدہ بدعات کی تائید و حمایت پر مشتمل اقوال سے بھر دیا۔ مثلاً معتزلہ میں سے زمخشری رمانی جہائی اور شیعہ اثنا عشریہ میں سے طبرسی اور ملاحسن کاشی وغیرہ جن فقہاء نے تفسیریں تحریر کی تھیں وہ صرف فقہی فروعات کے دلائل ذکر کرنے تک محدود رہے۔ مثلاً جصاص اور قرطبی وغیر ہما۔ مورخین کی تفاسیر دیکھنے سے یوں معلوم ہوتا ہے کہ قرآن دنیا میں صرف تاریخ پڑھانے کے لیے نازل ہوا ہے۔ صوفیاء نے قرآنی آیات سے ایسے اشارات کا استخراج کیا جو","ان کے مسلک اور وجدان وریاضت سے میل کھاتا تھا۔ ان میں ابن عربی اور ابو عبد الرحمن السلمی کے اسماء قابل ذکر ہیں۔ خلاصہ یہ کہ جو شخص بھی کسی فن یا مذہب میں ممتاز تھا اس نے قرآن مجید کو اپنے فن کے قالب میں ڈھالنے کی مقدور بھر کوشش کی ۔ تفسیر کے علاوہ قرآن مجید کے خاص خاص مباحث پر جدا گانہ اور مستقل تصانیف کا سلسلہ شروع ہوا۔ کسی نے صرف مسائل فقہیہ پر بحث کی ۔ کسی نے اسباب نزول پر کتاب لکھی۔ کسی نے صرف غیر زبانوں کے الفاظ کو جمع کیا ۔ کسی نے امثال قرآنی کو یکجا کیا۔ کسی نے آیات مکررہ کے نکات بیان کیے اس قسم کے مضامین کی تعداد اسی کے قریب پہنچی اور قریباً ہر ایک پر الگ الگ مستقل کتا ہیں لکھی گئیں ۔ ( مقد مہ الاتقان فی علوم القرآن للسیوطی ) مقدمہ","یہ تصنیفات اگر چہ بے شمار ہیں لیکن ان سب کو چھ قسموں پر تقسیم کیا جاسکتا ہے۔","(1) تفسیر فقهی : جن میں صرف ان آیتوں کو یکجا کیا ہے جن سے کوئی فقہی مسئلہ مستنبط ہوتا ہے، مثلاً احکام القرآن، اسماعیل بن اسحاق ۔ احکام القرآن، ابوبکر رازی۔ احکام القرآن ، قاضی یحیی بن اکثم ۔","(2) تفسیر اولی:","ان تصنیفات میں قرآن مجید کا فصاحت و بلاغت کے اعتبار سے معجز اور بے نظیر ہونا ثابت کیا ہے۔ اسی سلسلہ میں وہ تصنیفات بھی شامل ہیں جو قرآن مجید کی حقیقت و مجاز تشبیہات و استعارات مکررات صنائع و بدائع وغیرہ پرلکھی گئیں۔ (3) تفسیر تاریخی:","قرآن مجید میں انبیائے سابقین اور بزرگوں کے جو قصے مذکور ہیں، ان کی تفصیل اور مزید حالات۔","(4) تفسیر نحوی:","جن میں قرآن مجید کے نحوی مسائل سے بحث کی ہے۔ مثلاً اعراب القرآن رازی وغیرہ۔","(5) تفسیر لغوی:","یعنی قرآن مجید کے الفاظ مفردہ کے معانی اور ان کی تحقیق ۔ مثلاً مفردات القرآن، امام راغب ولغات القرآن ابوعبیدہ وغیرہ۔","(6) تفسیر کلامی:","جن آیتوں سے عقائد کے مسائل مستنبط ہوتے ہیں، ان پر بحث۔","ان مضامین میں سے فقہی مباحث پر جو کچھ لکھا گیا ہے اس پر اضافہ کی بہت کم گنجائش ہے۔ اس کی وجہ یہ ہے کہ اس بحث پر بڑے بڑے ائمہ فن نے طبع آزمائیاں کیں۔ امام یحیی ، قاضی یحیی بن اکثم ، ابوبکر رازی جس پایہ کے لوگ تھے۔ سب کو معلوم ہے۔ اسی طرح لغات قرآن اور نحوی مسائل پر جو کچھ لکھا گیا اس سے بڑھ کر نہیں لکھا جاسکتا۔ فصاحت و بلاغت کے متعلق نہایت کثرت سے کتابیں لکھی گئیں۔ جو اعجاز القرآن کے نام سے مشہور ہیں ۔ ان میں فصاحت و بلاغت کے تمام اقسام سے بحث کی ہے۔ غالباً سب سے پہلے جاحظ نے اس موضوع پر لکھا۔ پھر محمد بن یزید واسطی، عبد القاهر جرجانی، رمانی، خطابی، زملکانی اور قاضی ابو بکر باقلانی نے بسیط اور مفصل کتا بیں لکھیں۔ یہ کتا بیں آج بالکل","مفقود ہیں ۔","عبد القاہر جرجانی جوفن بلاغت کا موجد ہے۔ اس کی اعجاز القرآن آج دستیاب نہیں ۔ البتہ اس کی دوکتا ہیں دلائل الاعجاز اور اسرار البلاغہ جو خاص فن بلاغت میں ہیں عام طور سے ملتی ہیں۔ ان کتابوں میں اس نے جو نکتہ آفرینیاں کی ہیں۔ وہ حیرت انگیز ہیں۔ اس لیے اندازہ یہ ہے کہ قرآن مجید پر اس نے جو کچھ لکھا ہو گا بے مثل ہوگا۔ اسی طرح جاحظ کی تصنیف بھی بے نظیر ہوگی۔ اعجاز القرآن کے علاوہ اور بہت سی تصنیفات ہیں جن پر انشاء پردازی کی خاص خاص قسموں سے بحث کی ہے۔ مثلاً ابن ابی الاصبع نے قرآن مجید کے صنائع و بدائع پر مستقل کتاب لکھی۔ عز الدین بن عبد السلام نے قرآن کے مجازات کو یکجا کیا۔ ابوالحسن ماوردی نے قرآن کی ضرب الامثال جمع کیں اور ان کی خوبیاں بیان کیں ۔ علامہ سیوطی نے سورتوں کے طریق ابتداء پر ایک رسالہ لکھا جس کا نام الخواطر السوانح فی اسرار الفواتح ہے۔ امام ابن قیم نے کتاب البیان اس موضوع پر لکھی کہ اللہ تعالیٰ نے قرآن مجید میں کثرت سے قسمیں کیوں کھائی ہیں۔","خلاصه:","خلاصہ یہ کہ آغاز نزول سے لے کر تا عصر حاضر مسلمانوں نے کتاب الہی کے ساتھ اعتناء کیا اور اس کے مطالب و معانی اور اسرار و نکات معلوم کرنے کے لیے جو مساعی جمیلہ انجام دی ہیں۔ دنیا کی کوئی قوم اس کی نظیر پیش نہیں کر سکتی ۔ مگر بایں ہمہ جہد وسعی قرآن کریم کی وسعت و جامعیت کا یہ عالم ہے کہ اس کے بحر معانی میں غواصی کرنے والے ہر شخص کو عجز و تقصیر کا اعتراف کیے بغیر چارہ نہیں۔ عہد رسالت سے لے کر دور حاضر تک ہزاروں تفاسیر لکھی گئیں اور لکھی جارہی ہیں۔ مگر قرآنی نکات واسرار ختم ہونے میں نہیں آتے ۔ امام رازی نے سورہ فاتحہ کی تفسیر میں دعویٰ کیا ہے کہ یہ دس ہزار مسائل پر مشتمل ہے اور اپنے دعوی کو دلائل کی روشنی میں ثابت کیا ہے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا:","قرآن میں پہلی اور پچھلی قوموں کے حالات مذکور ہیں۔ اس میں تمہارے فیصلہ جات بھی مرقوم ہیں۔ یہ فیصلہ کن کتاب ہے، مذاق پر مشتمل نہیں ۔ جو از راہ بغاوت اس کو نظر انداز کرے گا۔ اللہ اس کو توڑ پھوڑ دے گا۔ جو اس کو چھوڑ کر کسی اور کتاب سے ہدایت طلب کرے گا۔ اللہ تعالیٰ اس کو گمراہ کر دے گا۔ یہ اللہ کی مضبوط رہتی ہے۔ یہ ذکر حکیم اور صراط مستقیم ہے۔ اس کی وجہ سے خیالات میں بے راہ روی نہیں آتی اور نہ ہی زبان میں الجھن پیدا ہوتی ہے۔ علماء اس کو پڑھتے پڑھتے سیر نہیں ہوتے۔ بار بار پڑھنے کے باوجود اس سے اکتاہٹ اور ملال پیدا نہیں ہوتا۔ یہ وہی کتاب ہے کہ جب جنوں نے سنا تو بے ساختہ پکار اٹھے اِنا سَمِعْنَا قُرْآنًا عَجَبًا ہم نے عجیب قرآن سنا جو شخص قرآن کے مطابق بات کرے گا وہ سچ بولے گا اور جو اس پر عمل کرے اسے اجر دیا جائے گا۔ جو","اس کے مطابق فیصلہ کرے گا وہ عدل و انصاف سے کام لے گا اور جو اس کی جانب دعوت دے گا، وہ صراط مستقیم پر گامزن ہوگا ۔ (سنن ترمذی: 149/2)","تفسیر نورالہدیٰ","قرآن مجید اللہ تعالیٰ کی وہ عظیم کتاب ہدایت ہے جس کی تفہیم اور توضیح کے لیے علمائے امت نے ہر دور میں بے مثال خدمات سرانجام دیں۔ مختلف مناہج پر تفاسیر مرتب کیں جیسا کہ سطور بالا میں بیان ہوا ہے۔ اسی سلسلہ زریں میں زیر نظر کتاب تفسیر نور الہدی ایک نہایت مبارک و مفید کاوش ہے جس میں دور حاضر کی مقبول اور آسان فہم تفاسیر ، ابن کثیر ، تیسیر القرآن، تیسیر الرحمن، اصدق البیان ، احسن البیان اور تفسیر السعدی کو یکجا کر کے ایک حسین اور جامع مجموعہ پیش کیا گیا ہے۔ یہ مجموعہ اس اعتبار سے منفرد ہے کہ :","اس میں سادگی اور روانی کے ساتھ مضبوط اعتقادی و فقہی بنیاد موجود ہے۔ قرآن کے مطالب کی توضیح مختصر، مدلل اور عام فہم پیرائے میں یکجا کیا ہے۔","تفاسیر کے مابین مطابقت و تنوع دونوں کا خوبصورت امتزاج ملتا ہے۔","علم کے طلبہ، مدارس کے فضلاء، خطباء، ائمہ مساجد اور عام قارئین سب کے لیے یکساں مفید ہے۔ بھائی ابوحمزہ عبد الخالق صدیقی صلی اللہ علیہ وسلم نے مختلف تفاسیر کو جمع کرتے ہوئے جس حسن انتخاب، ترتیب و تہذیب، علمی دیانت اور اخلاص کا مظاہرہ کیا ہے وہ لائق تحسین ہے۔ اس مجموعے کی بدولت قاری کو ایک ہی مقام پر کئی مستند تفاسیر کا خلاصہ مل جاتا ہے، جس سے قرآن سمجھنے میں آسانی ، غور و فکر میں گہرائی اور تدبر میں وسعت پیدا ہوتی ہے۔","میں اللہ تعالیٰ سے دعا کرتا ہوں کہ اس کتاب کو قبول عام نصیب فرمائے ، اسے اہل علم اور عوام کے لیے نافع ومبارک","بنائے اور اسے مؤلف، ناشر اور جملہ معاونین و مساہمین کے لیے ذخیرہ آخرت بنادے۔","وآخر دعوانا أن الحمد لله رب العالمين","وصلى الله . على نبينا محمد وآله وصحبه وسلم","وكتبه","عبد اللہ ناصر رحمانی"]]],"pub":{"ur":"ادارہ انصار السنۃ پبلیکیشنز، لاہور","ar":"مؤسسة أنصار السنة للنشر، لاهور","en":"Ansar as-Sunnah Publications, Lahore"}}])